def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_pressure = 0
    desperate_count = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0.0))
                if prev.get('bid', 0.0) >= 120:
                    rich_pressure += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return min(budget, 20.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if day >= 8:
        urgency += 1

    supply_score = 0
    if supply >= 23:
        supply_score = 3
    elif supply >= 20:
        supply_score = 2
    elif supply >= 17:
        supply_score = 1

    if urgency == 0:
        if supply >= 23 and rich_pressure <= 1:
            bid = 58.0
        elif supply >= 20 and highest_prev < 100:
            bid = 42.0
        else:
            bid = 0.0
    elif urgency <= 2:
        if rich_pressure >= 2 and supply < 20:
            bid = 18.0
        else:
            bid = 55.0 + 6.0 * supply_score
    elif urgency <= 4:
        bid = 78.0 + 8.0 * supply_score
        if highest_prev >= 140:
            bid = max(bid, 118.0)
    else:
        bid = 125.0 + 10.0 * supply_score
        if highest_prev > 0:
            bid = max(bid, highest_prev + 2.0)

    if desperate_count >= 2 and urgency >= 3:
        bid += 8.0

    if avg_prev >= 130 and urgency <= 2:
        bid = min(bid, 35.0)

    reserve = 0.0
    if hp >= 5 and day <= 7:
        reserve = DAILY_SALARY * 2
    elif hp >= 3 and day <= 8:
        reserve = DAILY_SALARY

    max_affordable = budget - reserve
    if max_affordable < 0:
        max_affordable = 0.0

    bid = min(bid, budget)
    if urgency <= 2:
        bid = min(bid, max_affordable)

    if hp <= 2 or no_water_days >= 2:
        bid = min(max(bid, 110.0), budget)

    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # Cindy/Eric were high; use that as a pressure signal
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.3:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.8:
        pressure = 0.6
    else:
        pressure = 0.3

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Estimate how many water units are likely to be contested.
    # If supply is tight, we bid more to avoid falling behind.
    tightness = 0.0
    if supply <= float(WATER_REQ) + 6:
        tightness = 0.8
    elif supply <= float(WATER_REQ) + 10:
        tightness = 0.5
    else:
        tightness = 0.25

    # Base bid: aim to be competitive but not necessarily the top bidder.
    # Use hp/no_water_days to decide urgency.
    urgency = 0.0
    if hp <= 2.0 or no_water_days >= 2:
        urgency = 1.0
    elif hp <= 4.0 or no_water_days >= 1:
        urgency = 0.7
    else:
        urgency = 0.4

    # Target bid level: scale with pressure and urgency.
    # If others were bidding ~1.6x salary, we try to be a bit below the maximum.
    target = DAILY_SALARY * (0.55 + 0.35 * pressure + 0.25 * urgency + 0.15 * tightness)

    # If yesterday's max bid was extremely high, cap our aggressiveness slightly.
    if highest_prev_bid > DAILY_SALARY * 1.4:
        target = min(target, DAILY_SALARY * (0.95 + 0.1 * urgency))

    # If my hp is critical, push closer to top pressure.
    if hp <= 2.0:
        target = max(target, min(budget, DAILY_SALARY * 0.9))

    # Ensure we never bid negative and respect budget.
    bid = max(0.0, min(budget, target))

    # If budget is very low, still try to bid something proportional to avoid total starvation.
    if budget < DAILY_SALARY * 0.2:
        bid = max(0.0, min(budget, DAILY_SALARY * 0.15))

    return float(bid)

